Maybe fix with this kind of diff?

```diff
diff --git a/lib/API/CliUx.js b/lib/API/CliUx.js
index f9a0a89..3881200 100644
--- a/lib/API/CliUx.js
+++ b/lib/API/CliUx.js
@@ -221,7 +221,12 @@ UX.dispAsTable = function(list, interact_infos) {
   var current_user = '';

   if (os.userInfo)
-    current_user = os.userInfo().username;
+    try {
+      current_user = os.userInfo().username;
+    } catch (e) {
+      // For the case of unhandled error for uv_os_get_passwd
+      current_user = '';
+    }
   else
     current_user = process.env.USER || process.env.LNAME || process.env.USERNAME || process.env.SUDO_USER || process.env.C9_USER || process.env.LOGNAME;
     ;
```

